// The site build rules registry as text (spec TracyHQ/tracy#189): the reference doc every reader of the repo gets, and the
// block of the quickstart-contract skill that tells a template author what each rule needs declared. Generated by
// `scripts/build-rules/gen.mjs` from `build-rules.mjs`, so the doc and the skill can never say other than the registry.
// Pure: no file system.
import { BUILD_RULES, SITE_BUILD_RULES, declarationsOf } from './build-rules.mjs'

const CMS_NAMES = Object.freeze({ joomla: 'Joomla', wordpress: 'WordPress', emdash: 'EmDash' })
const yesNo = (v) => (v ? 'yes' : 'no')

/** One declaration as a line a template author reads. */
function declarationLine(d) {
  if (d.lint) return `packing rule \`${d.lint}\``
  if (d.problems) return `\`${d.key}\` in the content map: ${d.what} (\`${d.problems}\`)`
  if (d.file) return `\`${d.file}\` beside the content map: ${d.what}`
  return `the slot roles: ${d.what}`
}

/** The reference doc, `docs/references/site-build-rules.md`. */
export function renderRulesDoc() {
  const lines = [
    '---',
    'description: The site build rules every brief build keeps, for every trade, template and CMS, generated from the one registry; what each guarantees the business owner, which final check judges it, whether it stops the build, and what a template must declare.',
    'sources:',
    '  - packages/wo/website-opportunities/domain/build-rules.mjs',
    '  - apps/tracy-web/src/opportunities-build/build-rule-checks.js',
    '  - packages/wo/website-opportunities/domain/build-blockers.mjs',
    '  - scripts/slot-roles/check.mjs',
    '---',
    '',
    '# Site build rules',
    '',
    '<!-- Generated by `node scripts/build-rules/gen.mjs` from `build-rules.mjs`. Edit the registry, not this file. -->',
    '',
    "A brief build turns a template into the business's own site. These rules hold for every site it builds, whatever the",
    'trade, the template or the CMS. Each rule lives once, in the registry',
    '(`packages/wo/website-opportunities/domain/build-rules.mjs`): its final checks run at the end of every build on the',
    "served pages, and their findings go on the build's receipt. A finding of a **blocker** rule makes the build end in",
    'Needs fixes; a **note** is reported only. A template gets the declarations below or the packing check',
    '(`scripts/slot-roles/check.mjs`) refuses it.',
    '',
    '## The six site build rules',
    '',
    ...Object.entries(SITE_BUILD_RULES).map(([n, text]) => {
      const carried = BUILD_RULES.filter((r) => r.siteRules.includes(Number(n))).map((r) => `\`${r.id}\``)
      return `${n}. ${text}. Carried by ${carried.join(', ')}.`
    }),
    '',
    '## Every rule',
    ''
  ]
  for (const rule of BUILD_RULES) {
    lines.push(`### \`${rule.id}\` (${rule.severity})`, '', `${rule.guarantee}.`, '')
    lines.push(`- Checked by: ${rule.checks.map((c) => `\`${c}\``).join(', ')} (\`build-rule-checks.js\`).`)
    if (rule.prompt) lines.push(`- Writers that take its words: ${rule.prompt.writers.join(', ')}.`)
    lines.push(
      `- A template declares: ${rule.declares.length ? rule.declares.map(declarationLine).join('; ') : 'nothing'}.`
    )
    lines.push(
      `- Writer and check per CMS: ${Object.entries(CMS_NAMES)
        .map(
          ([key, name]) =>
            `${name} writer ${yesNo(rule.cms[key]?.writer)}, check ${yesNo(rule.cms[key]?.check)}`
        )
        .join('; ')}.`,
      ''
    )
  }
  return `${lines.join('\n').trimEnd()}\n`
}

/** The generated block of the quickstart-contract skill: what a template must declare, rule by rule. */
export function renderContractBlock() {
  const lines = [
    '   <!-- build-rules:start (generated by `node scripts/build-rules/gen.mjs`; edit `build-rules.mjs`) -->',
    '   **What the site build rules need declared (generated from the registry):** `scripts/slot-roles/check.mjs "$P/$VER"`',
    '   refuses the contract while a content-map declaration below is missing or malformed. The full list of rules and their',
    '   checks: [`docs/references/site-build-rules.md`](../../../docs/references/site-build-rules.md).'
  ]
  for (const d of declarationsOf()) lines.push(`   - \`${d.rule}\`: ${declarationLine(d)}`)
  lines.push('   <!-- build-rules:end -->')
  return lines.join('\n')
}

/** The skill text with its generated block replaced (or placed before `before` when it has none yet). */
export function withContractBlock(skill, before) {
  const mark = skill.indexOf('<!-- build-rules:start')
  const start = mark < 0 ? -1 : skill.lastIndexOf('\n', mark) + 1
  const endMark = '<!-- build-rules:end -->'
  const end = skill.indexOf(endMark)
  if (start >= 0 && end > start)
    return skill.slice(0, start) + renderContractBlock() + skill.slice(end + endMark.length)
  const at = skill.indexOf(before)
  if (at < 0) throw new Error('the skill has no place for the build rules block')
  return `${skill.slice(0, at)}${renderContractBlock()}\n${skill.slice(at)}`
}
